/**
 * 문의 한 건의 모양·검증·문장 구성. 브라우저(src/scripts/contact.ts)와 서버(worker/index.ts)가
 * 같은 파일을 쓴다 — 두 쪽 규칙이 어긋나지 않게.
 */

export const TYPE_LABELS: Record<string, string> = {
  project: '공동 서비스 개발',
  technical: 'AI·기술 협업',
  partnership: '서비스·데이터 제휴',
  advertising: '브랜드·광고 협업',
  service: '서비스 이용·도입',
  other: '기타 문의',
};

export const LIMITS = {
  name: 40,
  company: 60,
  email: 254,
  messageMin: 10,
  messageMax: 3000,
} as const;

export interface Inquiry {
  type: string;
  name: string;
  company: string;
  /** 회신받을 이메일 — 서버 발송 방식에서만 받는다 */
  email: string;
  message: string;
  /** 개인정보 수집·이용 동의 — 서버 발송 방식에서만 */
  consent: boolean;
}

export type InquiryErrors = Partial<Record<keyof Inquiry, string>>;

const EMAIL_RE = /^[^\s@<>()[\]\\,;:"]+@[^\s@<>()[\]\\,;:"]+\.[^\s@<>()[\]\\,;:"]{2,}$/;

export function isEmail(s: string): boolean {
  return s.length <= LIMITS.email && EMAIL_RE.test(s);
}

/**
 * @param needsReply 서버 발송 방식이면 true — 회신 이메일과 동의를 함께 검사한다.
 *   이메일 앱으로 보내는 방식에서는 보낸 사람 주소를 메일 앱이 채우므로 받지 않는다.
 */
export function validate(v: Inquiry, needsReply = false): InquiryErrors {
  const e: InquiryErrors = {};
  if (!TYPE_LABELS[v.type]) e.type = '문의 유형을 골라 주세요.';
  const name = v.name.trim();
  if (!name) e.name = '이름 또는 담당자명을 적어 주세요.';
  else if (name.length > LIMITS.name) e.name = `이름은 ${LIMITS.name}자 이내로 적어 주세요.`;
  if (v.company.trim().length > LIMITS.company) e.company = `회사명은 ${LIMITS.company}자 이내로 적어 주세요.`;
  if (needsReply) {
    const email = v.email.trim();
    if (!email) e.email = '답장받을 이메일을 적어 주세요.';
    else if (!isEmail(email)) e.email = '이메일 형식을 확인해 주세요. 예: name@company.com';
  }
  const msg = v.message.trim();
  if (!msg) e.message = '문의 내용을 적어 주세요.';
  else if (msg.length < LIMITS.messageMin) e.message = `문의 내용을 ${LIMITS.messageMin}자 이상 적어 주세요.`;
  else if (msg.length > LIMITS.messageMax) e.message = `문의 내용은 ${LIMITS.messageMax.toLocaleString('ko-KR')}자 이내로 적어 주세요.`;
  if (needsReply && !v.consent) e.consent = '개인정보 수집·이용에 동의해 주세요.';
  return e;
}

/** 제목에 줄바꿈이 끼어 머리글을 바꾸지 못하게 한 줄로 만든다 */
const oneLine = (s: string) => s.replace(/[\r\n\t]+/g, ' ').trim();

export function composeSubject(v: Inquiry): string {
  const who = oneLine(v.company) || oneLine(v.name);
  return `[이룸엑스 문의] ${TYPE_LABELS[v.type] ?? '문의'} — ${who}`.slice(0, 160);
}

/** to 가 있으면 첫 줄에 받는 주소를 적는다 — 복사·저장한 내용을 어디로 보낼지 알 수 있게 */
export function composeText(v: Inquiry, to?: string): string {
  return [
    ...(to ? [`받는 곳: ${to}`, ''] : []),
    `문의 유형: ${TYPE_LABELS[v.type] ?? ''}`,
    `이름(담당자): ${oneLine(v.name)}`,
    `회사명: ${oneLine(v.company) || '적지 않음'}`,
    ...(v.email.trim() ? [`회신 이메일: ${oneLine(v.email)}`] : []),
    '',
    '문의 내용:',
    v.message.trim(),
    '',
    '—',
    '이룸엑스 웹사이트(www.irumx.app) 문의 페이지에서 작성한 내용입니다.',
  ].join('\n');
}

/** RFC 6068: 줄바꿈은 CRLF, 값은 퍼센트 인코딩 */
export function mailtoHref(to: string, subject: string, body: string): string {
  const enc = (s: string) => encodeURIComponent(s.replace(/\r?\n/g, '\r\n'));
  return `mailto:${to}?subject=${enc(subject)}&body=${enc(body)}`;
}

/** 서버 응답의 오류 코드 → 방문자에게 보일 문장 */
export const SEND_ERRORS: Record<string, string> = {
  invalid: '입력 내용을 확인해 주세요.',
  verification: '자동 등록 방지 확인을 통과하지 못했습니다. 잠시 뒤 다시 보내 주세요.',
  rate_limited: '짧은 시간에 여러 번 보내셨습니다. 1분쯤 뒤에 다시 보내 주세요.',
  rejected: '문의를 보내지 못했습니다. 아래 방법으로 직접 보내 주세요.',
  send_failed: '메일 서버 문제로 문의를 보내지 못했습니다. 잠시 뒤 다시 시도하시거나 아래 방법으로 보내 주세요.',
  unavailable: '지금은 문의를 보낼 수 없습니다. 아래 방법으로 직접 보내 주세요.',
  network: '네트워크 연결을 확인한 뒤 다시 보내 주세요.',
};
import { expect, test, type Page } from '@playwright/test';

// 보내기 방식(기본). wrangler dev 의 Worker 가 Turnstile 테스트 키로 확인하고, 가짜 Resend(8822)로 보낸다.
const MOCK = 'http://127.0.0.1:8822/__mails';
let ipSeq = 0;
const freshIp = () => `10.0.${Math.floor(Math.random() * 200)}.${++ipSeq}`;

async function mails(page: Page) {
  return (await (await page.request.get(MOCK)).json()) as {
    headers: Record<string, string>;
    body: { from: string; to: string[]; reply_to: string; subject: string; text: string };
  }[];
}

/** 브라우저 요청마다 다른 IP 로 보이게 해 IP 별 속도 제한이 테스트끼리 섞이지 않게 한다(운영에서는 Cloudflare 가 덮어쓴다) */
async function isolateIp(page: Page) {
  const ip = freshIp();
  page.on('request', (r) => {
    if (r.url().endsWith('/api/inquiry')) {
      const b = JSON.parse(r.postData() ?? '{}');
      console.log(`[req] elapsedMs=${b.elapsedMs} website=${JSON.stringify(b.website)} token=${String(b.token).slice(0, 12)}`);
    }
  });
  page.on('response', async (r) => {
    if (r.url().endsWith('/api/inquiry')) console.log(`[api] ${r.status()} ${await r.text().catch(() => '')}`);
  });
  // headers() 는 Origin 같은 보안 헤더를 빼고 돌려준다 — allHeaders() 로 전부 넘긴다
  await page.route('**/api/inquiry', async (route) =>
    route.continue({ headers: { ...(await route.request().allHeaders()), 'cf-connecting-ip': ip } }),
  );
}

/**
 * 실제 경과 시간으로 기다린다(단조 시계 기반 setTimeout). 이 PC 의 벽시계가 테스트 도중 뒤로 보정되어
 * Date.now 로 잰 작성 시간이 2.4초로 나오던 간헐 실패가 있었다 — 문의 도구는 이제 performance.now 로 잰다.
 */
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

async function fill(page: Page, message: string) {
  // 문의 도구 초기화(작성 시간 측정 시작)를 기다린 뒤 입력한다
  await page.locator('[data-contact-tool][data-ready="true"]').waitFor();
  await page.getByLabel('AI·기술 협업').check();
  await page.locator('#c-name').fill('테스트 담당자');
  await page.locator('#c-email').fill('tester@example.com');
  await page.locator('#c-company').fill('테스트 회사');
  await page.locator('#c-message').fill(message);
  await page.locator('#c-consent').check();
}

test.describe('문의 보내기', () => {
  test.describe.configure({ mode: 'serial' });

  test('화면: 보내기 버튼·답장 이메일·동의·직접 보내기 안내', async ({ page }) => {
    await page.goto('/contact');
    await expect(page.getByRole('button', { name: '문의 보내기' })).toBeVisible();
    await expect(page.getByLabel('답장받을 이메일')).toBeVisible();
    await expect(page.getByText('개인정보 수집·이용 동의')).toBeVisible();
    await expect(page.getByText('답변을 마친 날로부터 1년').first()).toBeVisible();
    await expect(page.getByText('문의 채널을 준비하고 있습니다.')).toHaveCount(0);
    await expect(page.locator('a[href="mailto:help@irumx.app"]').first()).toBeVisible();
  });

  test('빈 입력: 답장 이메일과 동의까지 오류로 알려 준다', async ({ page }) => {
    await page.goto('/contact');
    await page.getByRole('button', { name: '문의 보내기' }).click();
    const summary = page.locator('[data-errors]');
    await expect(summary).toBeFocused();
    await expect(summary).toContainText('답장받을 이메일을 적어 주세요.');
    await expect(summary).toContainText('개인정보 수집·이용에 동의해 주세요.');
    await page.locator('#c-email').fill('not-an-email');
    await page.getByRole('button', { name: '문의 보내기' }).click();
    await expect(summary).toContainText('이메일 형식을 확인해 주세요.');
  });

  test('보내면 help@irumx.app 로 한 통 발송되고 접수 화면이 나온다', async ({ page }) => {
    await page.request.delete(MOCK);
    await isolateIp(page);
    await page.goto('/contact?type=technical');
    await fill(page, '사내 문서 검색 자동화를 함께 만들고 싶습니다. 테스트 문의입니다.');
    await sleep(3100); // 서버는 3초보다 빨리 채운 양식을 자동 등록으로 본다
    await page.getByRole('button', { name: '문의 보내기' }).click();

    const done = page.locator('[data-success]');
    await expect(done).toBeVisible({ timeout: 30_000 });
    await expect(page.getByRole('heading', { name: '문의가 접수되었습니다.' })).toBeFocused();
    await expect(done).toContainText('tester@example.com');

    const sent = await mails(page);
    expect(sent).toHaveLength(1);
    const m = sent[0];
    expect(m.body.to).toEqual(['help@irumx.app']);
    expect(m.body.reply_to).toBe('tester@example.com');
    expect(m.body.from).toContain('@irumx.app');
    expect(m.body.subject).toBe('[이룸엑스 문의] AI·기술 협업 — 테스트 회사');
    expect(m.body.text).toContain('사내 문서 검색 자동화');
    expect(m.body.text).toContain('회신 이메일: tester@example.com');
    expect(m.headers['idempotency-key']).toMatch(/^irumx-inquiry\/[0-9a-f-]{36}$/);
    expect(m.headers['authorization']).toBe('Bearer re_test_only');

    // 입력값이 주소·브라우저 저장소에 남지 않는다
    expect(page.url()).toMatch(/\/contact\?type=technical$/);
    const stored = await page.evaluate(() => ({ l: localStorage.length, s: sessionStorage.length, c: document.cookie }));
    expect(stored).toEqual({ l: 0, s: 0, c: '' });

    // 새 문의 작성
    await page.getByRole('button', { name: '새 문의 작성' }).click();
    await expect(page.locator('#c-message')).toHaveValue('');
    await expect(done).toBeHidden();
  });

  test('발송이 실패하면 성공으로 보이지 않고 다른 보낼 방법을 보여 준다', async ({ page }) => {
    await page.request.delete(MOCK);
    await isolateIp(page);
    await page.goto('/contact');
    await fill(page, '[fail] 메일 서버 실패를 흉내 내는 문의입니다.');
    await sleep(3100);
    await page.getByRole('button', { name: '문의 보내기' }).click();
    await expect(page.locator('[data-status]')).toContainText('메일 서버 문제로 문의를 보내지 못했습니다', {
      timeout: 30_000,
    });
    await expect(page.locator('[data-success]')).toBeHidden();
    const alt = page.locator('[data-alt]');
    await expect(alt).toBeVisible();
    await expect(alt.getByRole('button', { name: '이메일 앱으로 작성' })).toBeVisible();
    await expect(alt.getByRole('button', { name: '문의 내용 복사' })).toBeVisible();
    expect(await mails(page)).toHaveLength(0);
  });
});

test.describe('문의 API', () => {
  const good = () => ({
    type: 'project',
    name: '담당자',
    company: '',
    email: 'api@example.com',
    message: '열 글자를 넘는 API 테스트 문의입니다.',
    consent: true,
    token: 'XXXX.DUMMY.TOKEN.XXXX',
    submissionId: crypto.randomUUID(),
    elapsedMs: 5000,
    website: '',
  });
  const post = (page: Page, data: unknown, headers: Record<string, string> = {}) =>
    page.request.post('/api/inquiry', {
      data,
      headers: { Origin: 'http://127.0.0.1:8820', 'CF-Connecting-IP': freshIp(), ...headers },
    });

  test('다른 출처에서 온 요청은 거절', async ({ page }) => {
    const res = await post(page, good(), { Origin: 'https://evil.example' });
    expect(res.status()).toBe(403);
    expect((await res.json()).code).toBe('rejected');
  });

  test('GET 은 405, 없는 API 는 404', async ({ page }) => {
    expect((await page.request.get('/api/inquiry')).status()).toBe(405);
    expect((await page.request.get('/api/nothing')).status()).toBe(404);
  });

  test('미끼 칸·너무 빠른 작성은 거절', async ({ page }) => {
    const hp = await post(page, { ...good(), website: 'http://spam.example' });
    expect(hp.status()).toBe(400);
    expect((await hp.json()).code).toBe('rejected');
    const fast = await post(page, { ...good(), elapsedMs: 500 });
    expect(fast.status()).toBe(400);
  });

  test('서버도 입력을 검증한다(브라우저 검증을 건너뛴 요청)', async ({ page }) => {
    const res = await post(page, { ...good(), email: 'bad', consent: false, message: '짧음' });
    expect(res.status()).toBe(400);
    const body = await res.json();
    expect(body.code).toBe('invalid');
    expect(Object.keys(body.fields).sort()).toEqual(['consent', 'email', 'message']);
  });

  test('Turnstile 토큰이 없으면 거절', async ({ page }) => {
    const res = await post(page, { ...good(), token: '' });
    expect(res.status()).toBe(403);
    expect((await res.json()).code).toBe('verification');
  });

  // 로컬(wrangler dev)의 요청 제한은 시간 창 단위로 센다. 네 요청 사이에 창이 바뀌거나 이 PC(WSL)의 벽시계가
  // 보정되면 세기가 처음부터 다시 시작돼 드물게 403 이 나온다(2026-10-08, 반복 30회 중 0회·전체 실행 중 1회).
  // 운영의 요청 제한은 Cloudflare 가 하므로, 이 시험만 한 번 다시 돌려 환경 탓 실패를 거른다.
  test.describe('요청 제한', () => {
    test.describe.configure({ retries: 1 });
    test('같은 IP 에서 1분에 4번째 요청은 429', async ({ page }) => {
      const ip = freshIp();
      const codes: number[] = [];
      for (let i = 0; i < 4; i++) {
        // 검증 단계에서 멈추는 요청(토큰 없음)으로 세어 실제 발송은 일어나지 않게 한다
        const res = await post(page, { ...good(), token: '' }, { 'CF-Connecting-IP': ip });
        codes.push(res.status());
      }
      expect(codes.slice(0, 3)).toEqual([403, 403, 403]);
      expect(codes[3]).toBe(429);
    });
  });
});
