import { defineConfig, devices } from '@playwright/test';

/**
 * 브라우저 자동화 테스트.
 *   npm run test:build   # dist(보내기 방식, Turnstile 테스트 키) · dist-draft(준비 중) · dist-email(이메일 앱 방식)
 *   npm test
 *
 * - desktop/mobile: wrangler dev 로 실제 Workers(정적 자산 + /api/inquiry)를 띄운다.
 *   Turnstile 은 Cloudflare 가 공개한 테스트 키(항상 통과), Resend 는 가짜 서버(tests/mock-resend.mjs)로 보낸다.
 * - draft, email: 해당 방식으로 만든 빌드를 정적 서버로 띄운다.
 */
export default defineConfig({
  testDir: './tests',
  timeout: 45_000,
  // 가짜 Resend 서버의 발송 기록을 여러 파일이 함께 쓰므로 한 줄로 돌린다
  workers: 1,
  reporter: [['list']],
  use: { locale: 'ko-KR', trace: 'off' },
  // 시험 포트는 8820~8823 — 8788·8789 는 같은 PC 의 다른 프로젝트(yeopjari-your·insight)가 쓴다.
  // 남의 서버를 재사용하면 엉뚱한 화면을 시험하므로 재사용하지 않는다(포트가 차 있으면 바로 실패).
  webServer: [
    { command: 'node tests/mock-resend.mjs 8822', url: 'http://127.0.0.1:8822/__mails', reuseExistingServer: false },
    {
      command: 'npx wrangler dev --port 8820 --ip 127.0.0.1 --env-file tests/worker-test.env',
      url: 'http://127.0.0.1:8820/',
      reuseExistingServer: false,
      timeout: 60_000,
    },
    { command: 'node scripts/serve-static.mjs dist-draft 8821', url: 'http://127.0.0.1:8821/', reuseExistingServer: false },
    { command: 'node scripts/serve-static.mjs dist-email 8823', url: 'http://127.0.0.1:8823/', reuseExistingServer: false },
  ],
  projects: [
    {
      name: 'desktop',
      testMatch: /(site|contact-send|inbound)\.spec/,
      use: { ...devices['Desktop Chrome'], viewport: { width: 1280, height: 800 }, baseURL: 'http://127.0.0.1:8820' },
